          "Give candidates the same short description of the task and ask them to suggest an explanation sequence, required inputs and claims they would decline to make. An initial discussion can be brief. If selection requires a custom sample the brand could actually use, agree on scope and compensation before requesting production. Procurement should not quietly become unpaid creative work.\n\nReview whether facts connect, terminology suits the audience and unknown conditions remain visible. Asking someone to identify a sentence that readers could misunderstand often reveals more than asking whether they are an expert. Willingness to read a supplied script does not establish that the explanation is reliable.\n\nThe expert interview brief helps organize questions, materials and approval. Explain whether contributors may state limitations or disagree with an assumption. A commercial relationship should not turn a conditional conclusion into an unconditional recommendation. If the brand cannot provide a test environment, specifications or necessary documents, resolve that input gap first. The creator’s reputation is not a replacement for missing product evidence. A useful sample discussion tests how the person reasons with available information and where further work would be needed."
