          "State whether the brand is buying interview time, production, publication or another specific contribution. Sales-linked compensation, product access and a fixed fee are different arrangements. Calling someone a KOL does not remove the need to define the work. Relationships with another brand, employer or institution may also affect the proposed assignment.\n\nIn the United States advertising context, the FTC endorsement FAQ addresses honest, nonmisleading endorsements and appropriate disclosure of material connections. Expert status does not make a commercial relationship disappear. The operational recommendation here is to assign relationship checks, not to issue a legal finding about a particular person.\n\nRecord necessary questions and an owner without demanding unrelated private contracts. Check requirements for the actual market and platform. Carry the agreed disclosure approach through to the final asset and publication review instead of leaving it only in a payment email. Editorial review and commercial confirmation can have different owners, but someone must check whether the final version still expresses the agreed conditions accurately. This also prevents a researcher from mistaking an apparently independent public explanation for evidence of independence in a newly paid assignment."
