          "The campaign evidence log can retain actual observations beyond the announcement. For news requiring action, separately record original date, source, affected task, unknown condition, owner and next step. A bookmark collection does not explain whether anything has been done.\n\nSuppose a brand considers partnership advertising. Assign scope confirmation, demonstration, actual permission and asset conditions before deciding on a controlled pilot. This is a hypothetical workflow, not a claim that Roster or any account was tested. The owner should understand potential changes to terms, costs and production, beyond an additional marketing entry point.\n\nMark irrelevant or low-priority news as reference only. Monitoring does not require turning every item into a project or sending generic updates to people without a related task. Preserve the reason so the next colleague encountering the same release understands why adoption did not immediately follow. This makes the record useful even when the decision is to maintain the existing process."
